  { id_solicitud: 'DEV-1126', sku: 'MW-150', unidades: '1', monto: '79990',  dias_desde_compra: '8',  estado_producto: 'con_fallas',      email_cliente: 'cliente12@example.cl' },
  { id_solicitud: 'DEV-C01',  sku: 'CB-010', unidades: '1', monto: '9990',   dias_desde_compra: '1',  estado_producto: 'sin_abrir',       email_cliente: 'control01@example.cl' },
